public class FileProcessor {
    // 'throws' declares the contract: caller must handle this
    public void readFile(String path) throws java.io.IOException {
        if (path == null) {
            // 'throw' executes the logic to interrupt flow
            throw new IllegalArgumentException("Path cannot be null");
        }
        // Potential checked exception propagated to caller
        throw new java.io.IOException("File not found");
    }
}
